const raw = $input.first().json.stdout;
const filas = JSON.parse(raw);
const headers = filas[0];
const data = filas.slice(1);

const hoy = new Date();
hoy.setHours(0, 0, 0, 0);

const idxFecha = headers.indexOf('Fecha');
const idxTarea = headers.indexOf('Tarea');
const idxEstado = headers.indexOf('Estado');
const idxHora = headers.findIndex(h => h.toString().trim().startsWith('Hora'));

const atrasadas = [];

for (const fila of data) {
  const estado = (fila[idxEstado] || '').toString().trim().toLowerCase();
  if (estado === 'hecho' || estado === 'completada') continue;

  const fechaStr = (fila[idxFecha] || '').toString().trim();
  if (!fechaStr) continue;

  const fechaTarea = new Date(fechaStr + 'T00:00:00');
  const diffDias = Math.floor((hoy - fechaTarea) / (1000 * 60 * 60 * 24));

  if (diffDias >= 2) {
    atrasadas.push({
      tarea: fila[idxTarea],
      fecha: fechaStr,
      hora: fila[idxHora] || '',
      dias_atraso: diffDias
    });
  }
}

atrasadas.sort((a, b) => b.dias_atraso - a.dias_atraso);

return [{ json: { atrasadas, total: atrasadas.length } }];

const data = $input.first().json;
const atrasadas = data.atrasadas;

let msg = `\u26a0\ufe0f <b>Vaca - Tareas atrasadas</b>\n\n`;
msg += `Tienes <b>${data.total}</b> tarea(s) con 2+ d\u00edas de atraso:\n\n`;

for (const t of atrasadas.slice(0, 10)) {
  msg += `\u2022 <b>${t.tarea}</b> (${t.fecha}) - ${t.dias_atraso} d\u00edas\n`;
}

if (atrasadas.length > 10) {
  msg += `\n...y ${atrasadas.length - 10} m\u00e1s.`;
}

msg += `\n\n\u00bfQuieres reagendarlas o completarlas? D\u00edle a Vaca.`;

return [{ json: { text: msg } }];
